# Helper function to load live telemetry JSON generated by backend orchestrator
def load_live_telemetry():
    telemetry_file = "live_scan_telemetry.json"
    if os.path.exists(telemetry_file):
        try:
            with open(telemetry_file, "r") as f:
                return json.load(f)
        except Exception:
            return None
    return None

